// ====================== EDIT THESE ======================
var API_KEY = 'PASTE_YOUR_OPENWEATHERMAP_KEY_HERE';      // your OpenWeatherMap API key
var CITY    = 'Chennai,IN';                         // city,country-code
var LAT = null, LON = null;                         // optional: e.g. LAT = 12.79; LON = 80.22;  (if set, used instead of CITY)
// ========================================================

if (API_KEY === 'PASTE_YOUR_OPENWEATHERMAP_KEY_HERE' || API_KEY === '') {
    // no key yet: tell the dashboard instead of calling the API
    return [null, { statusCode: 0, payload: { message: 'Add your OpenWeatherMap API key in the "Build OpenWeatherMap URL" node, then Deploy.' } }];
}
var q = (LAT !== null && LON !== null) ? ('lat=' + LAT + '&lon=' + LON) : ('q=' + encodeURIComponent(CITY));
msg.url = 'https://api.openweathermap.org/data/2.5/weather?' + q + '&units=metric&appid=' + encodeURIComponent(API_KEY);
return [msg, null];

// Inputs: (1) MQTT message from the STM32   (2) HTTP response from OpenWeatherMap
// Outputs: [0] comparison table   [1] verdict card

function f(v, d) { return (typeof v === 'number') ? v.toFixed(d) : '-'; }
function sgn(v, d) { return (v >= 0 ? '+' : '') + v.toFixed(d); }

// ---------- 1. remember whatever just arrived ----------
if (msg.statusCode !== undefined) {                       // came from the HTTP request
    if (msg.statusCode === 200 && msg.payload && msg.payload.main) {
        flow.set('owm', msg.payload);
        flow.set('owmErr', null);
    } else if (msg.statusCode === 0) {
        flow.set('owmErr', msg.payload.message);
    } else {
        var m = (msg.payload && msg.payload.message) ? msg.payload.message : 'no details';
        var hint = (msg.statusCode === 401) ? ' (a brand-new key can take up to 2 hours to activate)' : '';
        flow.set('owmErr', 'OpenWeatherMap error ' + msg.statusCode + ': ' + m + hint);
    }
} else {                                                  // came from MQTT
    var d = msg.payload;
    if (typeof d === 'string') {
        try { d = JSON.parse(d); } catch (e) { node.warn('Not valid JSON: ' + d); return null; }
    }
    if (!d || typeof d.temperature !== 'number' || typeof d.humidity !== 'number' || typeof d.pressure !== 'number') {
        node.warn('Missing temperature/humidity/pressure field'); return null;
    }
    flow.set('sensor', d);
}

var s = flow.get('sensor');
var w = flow.get('owm');
var err = flow.get('owmErr');

// ---------- 2. comparison table ----------
function level(absDiff, ok, warn) { return absDiff <= ok ? 'ok' : (absDiff <= warn ? 'warn' : 'bad'); }
function agree(l) { return l === 'ok' ? 'Close match' : (l === 'warn' ? 'Small gap' : 'Large gap'); }

var rows = [];
var note = [];
var times = '';
var title = 'Sensor vs OpenWeatherMap';

if (s && w) {
    var tz = w.timezone || 0;
    var hhmm = function (u) { return new Date((u + tz) * 1000).toISOString().substr(11, 5); };
    var place = w.name ? (w.name + (w.sys && w.sys.country ? ', ' + w.sys.country : '')) : 'your location';
    title = 'Sensor vs OpenWeatherMap (' + place + ')';
    times = 'Weather observation at ' + hhmm(w.dt) + ' local time. Sensor values are live.';

    var dT = s.temperature - w.main.temp;
    var dH = s.humidity - w.main.humidity;
    var dP = s.pressure - w.main.pressure;
    var lT = level(Math.abs(dT), 2, 5), lH = level(Math.abs(dH), 10, 20), lP = level(Math.abs(dP), 2, 5);

    rows = [
        { name: 'Temperature', sensor: f(s.temperature, 1) + ' °C',  owm: f(w.main.temp, 1) + ' °C',      diff: sgn(dT, 1) + ' °C',  level: lT, agree: agree(lT) },
        { name: 'Humidity',    sensor: f(s.humidity, 1) + ' %RH',    owm: f(w.main.humidity, 0) + ' %RH', diff: sgn(dH, 1) + ' %RH', level: lH, agree: agree(lH) },
        { name: 'Pressure',    sensor: f(s.pressure, 1) + ' hPa',    owm: f(w.main.pressure, 0) + ' hPa', diff: sgn(dP, 1) + ' hPa', level: lP, agree: agree(lP) }
    ];

    if (dT > 2)       { note.push('Your sensor is ' + dT.toFixed(1) + ' °C warmer than outside (indoor or sun-warmed spot).'); }
    else if (dT < -2) { note.push('Your sensor is ' + Math.abs(dT).toFixed(1) + ' °C cooler than outside (air-conditioned or shaded spot).'); }
    else              { note.push('Temperature agrees closely with the outside air.'); }
    if (Math.abs(dH) > 10) { note.push('Humidity differs by ' + Math.abs(dH).toFixed(0) + ' %RH, normal between indoors and outdoors.'); }
    if (Math.abs(dP) > 5)  { note.push('Pressure gap is larger than usual: OpenWeatherMap reports sea-level pressure, your sensor reads at its own altitude.'); }
} else if (s) {
    rows = [
        { name: 'Temperature', sensor: f(s.temperature, 1) + ' °C', owm: '-', diff: '-', level: 'wait', agree: 'waiting' },
        { name: 'Humidity',    sensor: f(s.humidity, 1) + ' %RH',   owm: '-', diff: '-', level: 'wait', agree: 'waiting' },
        { name: 'Pressure',    sensor: f(s.pressure, 1) + ' hPa',   owm: '-', diff: '-', level: 'wait', agree: 'waiting' }
    ];
    note.push('Waiting for OpenWeatherMap data...');
} else {
    note.push('Waiting for the first reading from the STM32...');
}

var out1 = { payload: { title: title, error: err, rows: rows, note: note.join(' '), times: times } };

// ---------- 3. verdict ----------
var v;
if (!w) {
    v = { emoji: '⏳', headline: 'Waiting for the weather', detail: err ? err : 'Fetching OpenWeatherMap data...', outside: '', bg: '#eceff1', fg: '#37474f' };
} else {
    var cond = (w.weather && w.weather[0]) ? w.weather[0] : { id: 800, description: 'clear sky' };
    var id = cond.id;
    var clouds = w.clouds ? w.clouds.all : 0;
    var rain = (w.rain && (w.rain['1h'] || w.rain['3h'])) || 0;
    var tOut = w.main.temp;
    var isDay = (w.sys && w.sys.sunrise && w.sys.sunset) ? (w.dt >= w.sys.sunrise && w.dt < w.sys.sunset) : true;

    var heavy = (id >= 200 && id < 300) || [502, 503, 504, 522, 771, 781].indexOf(id) >= 0 || rain >= 7.6;
    var light = !heavy && ((id >= 300 && id < 400) || (id >= 500 && id < 600) || rain > 0);
    var hazy  = !heavy && !light && id >= 700 && id < 800;

    var outside = 'Outside now: ' + cond.description + ', ' + tOut.toFixed(1) + ' °C, clouds ' + clouds + ' %, ' +
                  (rain > 0 ? 'rain ' + rain + ' mm/h' : 'no rain') + ', ' + (isDay ? 'daytime' : 'night') + '.';

    if (heavy) {
        v = { emoji: '🌧️', headline: 'Stay at home and have a cozy meal', detail: 'Heavy rain or a storm outside. Keep warm and dry, and enjoy something hot.', bg: '#cfd8e8', fg: '#1a2a4a' };
    } else if (light) {
        v = { emoji: '🌦️', headline: 'Light rain: keep an umbrella handy', detail: 'A short outing is fine, or enjoy a hot chai at home.', bg: '#dcecfa', fg: '#14395c' };
    } else if (hazy) {
        v = { emoji: '🌫️', headline: 'Hazy or misty: take it easy', detail: 'Visibility is low. A short walk is fine, skip long rides.', bg: '#e6e6e6', fg: '#333333' };
    } else if (id >= 600 && id < 700) {
        v = { emoji: '❄️', headline: 'Snow outside: stay warm indoors', detail: 'Have a warm drink and wait for it to clear.', bg: '#e8f1fb', fg: '#1a3a5a' };
    } else if (!isDay && clouds <= 30) {
        v = { emoji: '🌙', headline: 'Clear night: go for a calm night walk or ride', detail: 'No rain and a clear sky.', bg: '#1f2a44', fg: '#ffffff' };
    } else if (clouds <= 30) {
        var very = clouds <= 15;
        v = { emoji: '☀️', headline: (very ? 'Very sunny: go for a swim and have ice cream later! 🍦' : 'Mostly sunny: go for a swim and have ice cream later! 🍦'),
              detail: (tOut >= 35 ? 'It is very hot outside, so use sunscreen and drink plenty of water.' : 'Bright, dry weather outside.'), bg: '#fff3c4', fg: '#6b4e00' };
    } else {
        v = { emoji: '⛅', headline: 'Cloudy but dry: a great time for a ride', detail: 'Cloud cover ' + clouds + ' % and no rain.', bg: '#e3e9f0', fg: '#2c3e50' };
    }
    v.outside = outside;
    if (err) { v.detail += ' (OpenWeatherMap is failing right now, so this uses the last successful weather reading.)'; }
}
var out2 = { payload: v };

return [out1, out2];
